#pragma once

// Atomic single-slot fresh-voyage checkpoints in the Arduboy FX save region
// (sub-hauler-7px.24).
//
// The schema, cart partition and commit protocol are frozen by
// docs/progression-implementation.md sections 3-7 and 10. No internal EEPROM
// byte holds voyage data and schema 8 does not read, migrate or repair any
// earlier EEPROM or cart slot. This header is pure C++ so the host tests
// exercise the exact code the device compiles; Storage is the only place that
// touches the SPI cart.
//
// Contract summary:
//   * a 4 KiB save partition generated by `savesection 4096`, one erase block;
//   * one 512 B slot at offset 0: 16 B header + 495 B payload area + one commit
//     byte at slot+511;
//   * schema 8 scalar payload is 25 B, followed by the optional chart;
//   * CRC-16/CCITT-FALSE over header bytes 0..13 and exactly payload_length
//     payload bytes; the commit byte is outside the CRC;
//   * payload is encoded field by field, never as a raw C++ struct;
//   * load validates first and only then mutates the caller's state;
//   * a save erases the single 4 KiB block, writes page 0 then page 1 with the
//     commit byte last, and re-reads the slot. A power interruption during that
//     erase/write may lose the current checkpoint; it can never present invalid
//     data as loadable, and the title offers a clean New Voyage instead;
//   * no legacy chart/EEPROM block or migration path is read.
//
// The fixed build always stores schema 8 voyage checkpoints. Schema 7 slots are
// incompatible and are never migrated or partially applied.



#include <stdint.h>

#include "campaign.hpp"
#include "game.hpp"
#include "jobs.hpp"
#include "pilot.hpp"
#include "roster.hpp"
#include "world.hpp"
#include "chart.hpp"
#include "generated/exploration.hpp"

namespace voyage_save {

using game::State;

// ---------------------------------------------------------------------------
// Frozen layout
// ---------------------------------------------------------------------------

constexpr uint16_t kSaveBytes = 4096;
constexpr uint16_t kBlockBytes = 4096;
constexpr uint16_t kPagesPerBlock = 16;
constexpr uint16_t kPageBytes = 256;
constexpr uint16_t kSlotBytes = 512;
constexpr uint16_t kSlotOffset = 0;
constexpr uint16_t kHeaderBytes = 16;
constexpr uint16_t kPayloadCapacity = 495;
constexpr uint16_t kCommitOffset = 511;
constexpr uint8_t kCommitValid = 0x5A;

constexpr uint8_t kMagic0 = 0x53;   // 'S'
constexpr uint8_t kMagic1 = 0x48;   // 'H'
constexpr uint8_t kMagic2 = 0x56;   // 'V'
constexpr uint8_t kMagic3 = 0x59;   // 'Y'
constexpr uint8_t kSchemaVersion = 8;
constexpr uint8_t kCampaignContentVersion = 2;

constexpr uint16_t kMagicOffset = 0;
constexpr uint16_t kSchemaOffset = 4;
constexpr uint16_t kLayoutOffset = 5;
constexpr uint16_t kContentOffset = 6;
constexpr uint16_t kSignatureOffset = 7;
constexpr uint16_t kLengthOffset = 12;
constexpr uint16_t kCrcOffset = 14;
constexpr uint16_t kPayloadOffset = 16;

constexpr uint16_t kScalarBytes = 25;
constexpr uint16_t kChartBytes = world::CHART_BYTES;
constexpr uint16_t kPayloadBytes = kScalarBytes + kChartBytes;

static_assert(kSlotBytes == kHeaderBytes + kPayloadCapacity + 1, "slot is header + payload area + commit");
static_assert(kSlotOffset == 0, "single slot owns the save block");
static_assert(kSaveBytes == kBlockBytes, "save partition is one erase block");
static_assert(kSlotBytes <= kBlockBytes, "slot fits the erase block");
static_assert(kCommitOffset + 1 == kSlotBytes, "commit is the last slot byte");
static_assert(kPayloadOffset + kPayloadBytes <= kCommitOffset, "payload fits before the commit byte");
static_assert(kPayloadBytes <= kPayloadCapacity, "schema 8 payload fits its area");
static_assert(kScalarBytes == 25, "scalar payload is frozen at 25 bytes");

// Profile signature: one byte, schema 8. Chart presence is derived from bit 0;
// the shop bit is retired. Music has no saved field and is deliberately absent.
// Bits 1 and 2 are retired sonar and mines; bit 4 is retired hull damage.
constexpr uint8_t kSignatureFogChart = 1u << 0;
constexpr uint8_t kSignatureMultiHull = 1u << 5;
constexpr uint8_t kSignatureExploration = 1u << 6;

constexpr uint8_t kProfileSignature =
    kSignatureFogChart | kSignatureMultiHull | kSignatureExploration;
static_assert(kProfileSignature == 0x61, "schema 8 fixed-build signature is frozen");

// Result vocabulary shared by the storage transaction and the title
// integration. A missing slot is not a corrupt save; the title needs to tell
// blank, incompatible and corrupt data apart before offering NEW VOYAGE.
enum SlotStatus : uint8_t {
    kSlotBlank,
    kSlotValid,
    kSlotCorrupt,
    kSlotIncompatible,
};

struct SlotInfo {
    SlotStatus status;
};

// Single-slot inventory. There is no sequence, newest selection or fallback:
// one block erase owns the only checkpoint.
struct Inventory {
    SlotStatus status;
};

enum LoadResult : uint8_t {
    kLoaded,
    kNoSave,
    kCorruptSave,
    kIncompatibleSave,
};

enum SaveResult : uint8_t {
    kSaved,
    kInvalidState,
    kWriteFailed,
};

// ---------------------------------------------------------------------------
// Checksums and little-endian helpers
// ---------------------------------------------------------------------------

// CRC-16/CCITT-FALSE: poly 0x1021, init 0xFFFF, no reflection, no final XOR.
// The check vector "123456789" is 0x29B1 and is asserted by the host tests.
inline uint16_t crc16Update(uint16_t crc, uint8_t value) {
    crc ^= static_cast<uint16_t>(value) << 8;
    for (uint8_t bit = 0; bit < 8; ++bit)
        crc = static_cast<uint16_t>((crc & 0x8000u) ? ((crc << 1) ^ 0x1021u) : (crc << 1));
    return crc;
}

inline uint16_t crc16Bytes(const uint8_t *data, uint16_t length) {
    uint16_t crc = 0xFFFF;
    for (uint16_t i = 0; i < length; ++i)
        crc = crc16Update(crc, data[i]);
    return crc;
}

// ---------------------------------------------------------------------------
// Scalar payload (25 B, fixed field order)
// ---------------------------------------------------------------------------

// Transient only: 25 bytes, never persisted as a struct and never chart-sized.
// Bytes are field-encoded in the frozen order below; the C++ struct layout is
// deliberately not serialized.
struct Scalar {
    uint8_t bytes[kScalarBytes];
};

enum ScalarOffset : uint8_t {
    kFieldBerth = 0,
    kFieldHullClass = 1,
    kFieldTools = 2,
    kFieldPickups = 3,
    kFieldOpenGates = 4,
    kFieldSeenGates = 6,
    kFieldCampaign = 8,
    kFieldSurveys = 9,
    kFieldJobKind = 10,
    kFieldJobMission = 11,
    kFieldJobFrom = 12,
    kFieldJobTo = 13,
    kFieldJobCrates = 14,
    kFieldVoyageTicks = 15,
    kFieldDelivered = 19,
    kFieldRescues = 21,
    kFieldEnding = 23,
    kFieldPendingStory = 24,
};

static_assert(kFieldPendingStory + 1 == kScalarBytes, "scalar field table covers the payload");

// Pending scene ids are 0 (none) through story_view::kSceneMax (16): seven
// milestone/survey decks, eight departure/joint handoff scenes and the appended
// lower-right expedition result and briefing. This
// storage layer must not include the presentation header (its AVR draw path
// pulls the cart/music adapters into storage-only fixtures), so app.hpp pins
// the coupling.
constexpr uint8_t kPendingStoryNone = 0;
constexpr uint8_t kPendingStoryMax = 16;

inline uint8_t scalarU8(const Scalar &scalar, uint8_t offset) {
    return scalar.bytes[offset];
}

inline uint16_t scalarU16(const Scalar &scalar, uint8_t offset) {
    return static_cast<uint16_t>(scalar.bytes[offset] | (static_cast<uint16_t>(scalar.bytes[offset + 1]) << 8));
}

inline uint32_t scalarU32(const Scalar &scalar, uint8_t offset) {
    uint32_t value = scalar.bytes[offset];
    value |= static_cast<uint32_t>(scalar.bytes[offset + 1]) << 8;
    value |= static_cast<uint32_t>(scalar.bytes[offset + 2]) << 16;
    value |= static_cast<uint32_t>(scalar.bytes[offset + 3]) << 24;
    return value;
}

// The frozen schema-8 byte accepts the two retired ids (Minnow 0, Leviathan 2)
// so older voyages still validate and load; they are normalized to HAULER when
// applied. Unknown ids above 2 remain corrupt.
inline bool validHullClass(uint8_t value) {
    return roster::isValidId(value);
}

inline uint8_t toolsMask() {
    return static_cast<uint8_t>(exploration_data::CUTTER | exploration_data::SEAL | exploration_data::THRUSTER | exploration_data::LENS);
}

inline uint8_t pickupsMask() {
    return static_cast<uint8_t>((1u << exploration_data::PICKUP_COUNT) - 1u);
}

inline uint16_t gatesMask() {
    return static_cast<uint16_t>((1u << exploration_data::GATE_COUNT) - 1u);
}

// Validate the live checkpoint before erasing anything.
inline bool stateValidForSave(const State &state) {
    if (state.docked < 0 || state.docked >= static_cast<int8_t>(campaign::kBerthCount))
        return false;
    world::Berth berthInfo;
    if (!world::berthInfo(static_cast<uint8_t>(state.docked), berthInfo))
        return false;
    if (!validHullClass(state.hullClass))
        return false;
    if ((state.tools & static_cast<uint8_t>(~toolsMask())) != 0 || (state.pickups & static_cast<uint8_t>(~pickupsMask())) != 0)
        return false;
    if ((state.openGates & static_cast<uint16_t>(~gatesMask())) != 0 || (state.seenGates & static_cast<uint16_t>(~gatesMask())) != 0)
        return false;
    if (state.pendingStory > kPendingStoryMax)
        return false;
    if (!campaign::checkpointValid(state.campaign, state.surveys, state.ending, state.activeJob, state.tools))
        return false;
    // Restoration normally gates a service berth. A matching repair load can
    // legitimately occupy its work site before the milestone, and a short load
    // can leave the boat there after the job is cleared; the failed-delivery
    // note covers that second case. Loading still derives position from the
    // frozen berth table.
    if (!campaign::berthAvailable(state, static_cast<uint8_t>(state.docked)) && !jobs::deliveryFailed(state))
        return false;
    return world::berthInfo(static_cast<uint8_t>(state.docked), berthInfo);
}

// Serialize one scalar byte directly from live state. This replaces the former
// Scalar temporary on the save path; the field order is unchanged.
inline uint8_t statePayloadByte(const State &state, uint16_t index) {
    switch (index) {
    case kFieldBerth:
        return static_cast<uint8_t>(state.docked);
    case kFieldHullClass:
        // The live byte may still hold a legacy id until the next normalize;
        // every committed checkpoint writes the only playable hull.
        return static_cast<uint8_t>(roster::kDefault);
    case kFieldTools:
        return state.tools;
    case kFieldPickups:
        return state.pickups;
    case kFieldOpenGates:
        return static_cast<uint8_t>(state.openGates);
    case kFieldOpenGates + 1:
        return static_cast<uint8_t>(state.openGates >> 8);
    case kFieldSeenGates:
        return static_cast<uint8_t>(state.seenGates);
    case kFieldSeenGates + 1:
        return static_cast<uint8_t>(state.seenGates >> 8);
    case kFieldCampaign:
        return state.campaign;
    case kFieldSurveys:
        return state.surveys;
    case kFieldJobKind:
        return state.activeJob.kind;
    case kFieldJobMission:
        return state.activeJob.mission;
    case kFieldJobFrom:
        return state.activeJob.from;
    case kFieldJobTo:
        return state.activeJob.to;
    case kFieldJobCrates:
        return state.activeJob.crates;
    case kFieldVoyageTicks:
        return static_cast<uint8_t>(state.voyageTicks);
    case kFieldVoyageTicks + 1:
        return static_cast<uint8_t>(state.voyageTicks >> 8);
    case kFieldVoyageTicks + 2:
        return static_cast<uint8_t>(state.voyageTicks >> 16);
    case kFieldVoyageTicks + 3:
        return static_cast<uint8_t>(state.voyageTicks >> 24);
    case kFieldDelivered:
        return static_cast<uint8_t>(state.delivered);
    case kFieldDelivered + 1:
        return static_cast<uint8_t>(state.delivered >> 8);
    case kFieldRescues:
        return static_cast<uint8_t>(state.rescues);
    case kFieldRescues + 1:
        return static_cast<uint8_t>(state.rescues >> 8);
    case kFieldEnding:
        return state.ending;
    case kFieldPendingStory:
        return state.pendingStory;
    default:
        return 0xFF;
    }
}

inline uint8_t payloadByteFromState(const State &state
                                    ,
                                    const chart::State &chart
                                    ,
                                    uint16_t index) {
    if (index < kScalarBytes)
        return statePayloadByte(state, index);
    index = static_cast<uint16_t>(index - kScalarBytes);
    if (index < kChartBytes)
        return chart.explored[index];
    return 0xFF;
}

// A header byte is generated on demand; no 16-byte temporary is needed.
inline uint8_t headerByte(uint8_t index, uint16_t crc) {
    switch (index) {
    case kMagicOffset:
        return kMagic0;
    case kMagicOffset + 1:
        return kMagic1;
    case kMagicOffset + 2:
        return kMagic2;
    case kMagicOffset + 3:
        return kMagic3;
    case kSchemaOffset:
        return kSchemaVersion;
    case kLayoutOffset:
        return world::LAYOUT_VERSION;
    case kContentOffset:
        return kCampaignContentVersion;
    case kSignatureOffset:
        return kProfileSignature;
    case kLengthOffset:
        return static_cast<uint8_t>(kPayloadBytes);
    case kLengthOffset + 1:
        return static_cast<uint8_t>(kPayloadBytes >> 8);
    case kCrcOffset:
        return static_cast<uint8_t>(crc);
    case kCrcOffset + 1:
        return static_cast<uint8_t>(crc >> 8);
    default:
        return 0xFF;
    }
}

// Exact CRC the save transaction writes: header bytes 0..13 (the CRC field
// itself is outside that prefix, so the placeholder value is irrelevant)
// followed by every serialized payload byte in frozen field order. Pure and
// storage-free, so the App can compare live state against the last committed
// checkpoint before paying for an erase/page program.
inline uint16_t checkpointCrc(const State &state, const chart::State &chart) {
    uint16_t crc = 0xFFFF;
    for (uint8_t i = 0; i < kCrcOffset; ++i)
        crc = crc16Update(crc, headerByte(i, 0));
    for (uint16_t i = 0; i < kPayloadBytes; ++i)
        crc = crc16Update(crc, payloadByteFromState(state
                                                    ,
                                                    chart
                                                    ,
                                                    i));
    return crc;
}

template <typename Storage> inline uint8_t readPayloadU8(Storage &storage, uint16_t payload, uint8_t offset) {
    return storage.read(static_cast<uint16_t>(payload + offset));
}

template <typename Storage> inline uint16_t readPayloadU16(Storage &storage, uint16_t payload, uint8_t offset) {
    return static_cast<uint16_t>(readPayloadU8(storage, payload, offset) | (static_cast<uint16_t>(readPayloadU8(storage, payload, offset + 1)) << 8));
}

// Validate the serialized scalar fields in place. No Scalar or State temporary
// is built, so boot inspection and post-write read-back keep the save path's
// stack frame small.
template <typename Storage> inline bool payloadValid(Storage &storage, uint16_t payload) {
    const uint8_t berth = readPayloadU8(storage, payload, kFieldBerth);
    const uint8_t hullClass = readPayloadU8(storage, payload, kFieldHullClass);
    const uint8_t tools = readPayloadU8(storage, payload, kFieldTools);
    const uint8_t pickups = readPayloadU8(storage, payload, kFieldPickups);
    const uint8_t campaignMask = readPayloadU8(storage, payload, kFieldCampaign);
    const uint8_t surveys = readPayloadU8(storage, payload, kFieldSurveys);
    const uint8_t ending = readPayloadU8(storage, payload, kFieldEnding);
    const uint8_t pendingStory = readPayloadU8(storage, payload, kFieldPendingStory);

    if (pendingStory > kPendingStoryMax)
        return false;
    if (berth >= campaign::kBerthCount || !validHullClass(hullClass))
        return false;
    world::Berth berthInfo;
    if (!world::berthInfo(berth, berthInfo))
        return false;
    if ((tools & static_cast<uint8_t>(~toolsMask())) != 0 || (pickups & static_cast<uint8_t>(~pickupsMask())) != 0)
        return false;
    if ((readPayloadU16(storage, payload, kFieldOpenGates) & static_cast<uint16_t>(~gatesMask())) != 0 ||
        (readPayloadU16(storage, payload, kFieldSeenGates) & static_cast<uint16_t>(~gatesMask())) != 0)
        return false;

    game::ActiveJob job;
    job.kind = readPayloadU8(storage, payload, kFieldJobKind);
    job.mission = readPayloadU8(storage, payload, kFieldJobMission);
    job.from = readPayloadU8(storage, payload, kFieldJobFrom);
    job.to = readPayloadU8(storage, payload, kFieldJobTo);
    job.crates = readPayloadU8(storage, payload, kFieldJobCrates);
    if (!campaign::checkpointValid(campaignMask, surveys, ending, job, tools))
        return false;
    return campaign::berthAvailable(campaignMask, berth);
}

template <typename Storage> inline void readScalar(Storage &storage, uint16_t payload, Scalar &scalar) {
    for (uint8_t i = 0; i < kScalarBytes; ++i)
        scalar.bytes[i] = storage.read(static_cast<uint16_t>(payload + i));
}

template <typename Storage>
inline void writeSlot(Storage &storage, uint16_t crc, const State &state
                      ,
                      const chart::State &chart
) {
    // Page 0: 16 B header + payload bytes 0..239.
    storage.pageBegin(0);
    for (uint8_t i = 0; i < kHeaderBytes; ++i)
        storage.pageByte(headerByte(i, crc));
    for (uint16_t i = 0; i < kPageBytes - kHeaderBytes; ++i)
        storage.pageByte(payloadByteFromState(state
                                              ,
                                              chart
                                              ,
                                              i));
    storage.pageEnd();

    // Page 1: payload bytes 240..494 followed by the commit byte at 511.
    storage.pageBegin(1);
    for (uint16_t i = kPageBytes - kHeaderBytes; i < kPayloadCapacity; ++i)
        storage.pageByte(payloadByteFromState(state
                                              ,
                                              chart
                                              ,
                                              i));
    storage.pageByte(kCommitValid);
    storage.pageEnd();
}

// Read the 16-byte header once. Header fields and the CRC share these bytes,
// so validation does not issue the same cart reads twice.
template <typename Storage> inline void readHeader(Storage &storage, uint16_t base, uint8_t *header) {
    for (uint8_t i = 0; i < kHeaderBytes; ++i)
        header[i] = storage.read(static_cast<uint16_t>(base + i));
}

template <typename Storage> inline SlotInfo inspectSlot(Storage &storage) {
    SlotInfo info;
    info.status = kSlotBlank;

    uint8_t header[kHeaderBytes];
    readHeader(storage, kSlotOffset, header);
    const uint8_t commit = storage.read(static_cast<uint16_t>(kSlotOffset + kCommitOffset));

    // Blank requires both a non-magic prefix and a non-committed byte. A
    // present magic or commit byte means the slot belongs to this game even if
    // it is torn, corrupt, incompatible or in progress.
    const bool magic = header[kMagicOffset] == kMagic0 && header[kMagicOffset + 1] == kMagic1 && header[kMagicOffset + 2] == kMagic2 && header[kMagicOffset + 3] == kMagic3;
    if (!magic) {
        info.status = commit == kCommitValid ? kSlotCorrupt : kSlotBlank;
        return info;
    }
    if (commit != kCommitValid) {
        info.status = kSlotCorrupt;
        return info;
    }
    if (header[kSchemaOffset] != kSchemaVersion || header[kLayoutOffset] != world::LAYOUT_VERSION || header[kContentOffset] != kCampaignContentVersion ||
        header[kSignatureOffset] != kProfileSignature) {
        info.status = kSlotIncompatible;
        return info;
    }

    const uint16_t length = static_cast<uint16_t>(header[kLengthOffset] | (static_cast<uint16_t>(header[kLengthOffset + 1]) << 8));
    if (length != kPayloadBytes) {
        info.status = kSlotCorrupt;
        return info;
    }

    uint16_t crc = 0xFFFF;
    for (uint8_t i = 0; i < kCrcOffset; ++i)
        crc = crc16Update(crc, header[i]);
    for (uint16_t i = 0; i < length; ++i)
        crc = crc16Update(crc, storage.read(static_cast<uint16_t>(kSlotOffset + kPayloadOffset + i)));
    const uint16_t expected = static_cast<uint16_t>(header[kCrcOffset] | (static_cast<uint16_t>(header[kCrcOffset + 1]) << 8));
    if (crc != expected) {
        info.status = kSlotCorrupt;
        return info;
    }

    const uint16_t payload = static_cast<uint16_t>(kSlotOffset + kPayloadOffset);
    info.status = payloadValid(storage, payload) ? kSlotValid : kSlotCorrupt;
    return info;
}

template <typename Storage> inline Inventory inspect(Storage &storage) {
    Inventory inventory;
    inventory.status = inspectSlot(storage).status;
    return inventory;
}

// ---------------------------------------------------------------------------
// Load
// ---------------------------------------------------------------------------

// Put the boat on the generated dock anchor and snap the follow camera. The
// checkpoint scalar stores only the berth id; position and camera are derived
// from the baked berth table. New Voyage commits this berth before the flow
// layer moves the live boat beside it; Continue and recovery enter here.
inline bool positionAtBerth(State &state, uint8_t berthId) {
    world::Berth berth;
    if (!world::berthInfo(berthId, berth))
        return false;
    state.x = berth.pixel_x;
    state.y = berth.pixel_y;
    game::snapCamera(state);
    return true;
}

inline void applyScalar(const Scalar &scalar, State &state) {
    game::reset(state);

    state.docked = static_cast<int8_t>(scalarU8(scalar, kFieldBerth));
    // Keep the frozen byte at its offset but always restore the playable hull:
    // legacy Minnow(0)/Leviathan(2) checkpoints retain every other field.
    state.hullClass = static_cast<uint8_t>(roster::normalize(scalarU8(scalar, kFieldHullClass)));
    state.tools = scalarU8(scalar, kFieldTools);
    state.pickups = scalarU8(scalar, kFieldPickups);
    state.openGates = scalarU16(scalar, kFieldOpenGates);
    state.seenGates = scalarU16(scalar, kFieldSeenGates);
    state.campaign = scalarU8(scalar, kFieldCampaign);
    state.surveys = scalarU8(scalar, kFieldSurveys);
    state.activeJob.kind = scalarU8(scalar, kFieldJobKind);
    state.activeJob.mission = scalarU8(scalar, kFieldJobMission);
    state.activeJob.from = scalarU8(scalar, kFieldJobFrom);
    state.activeJob.to = scalarU8(scalar, kFieldJobTo);
    state.activeJob.crates = scalarU8(scalar, kFieldJobCrates);
    state.lastDelivery = 0;
    state.voyageTicks = scalarU32(scalar, kFieldVoyageTicks);
    state.delivered = scalarU16(scalar, kFieldDelivered);
    state.rescues = scalarU16(scalar, kFieldRescues);
    state.ending = scalarU8(scalar, kFieldEnding);
    state.pendingStory = scalarU8(scalar, kFieldPendingStory);

    // A checkpoint is always at a berth. Cargo is derived from the active
    // job; service restores full air and neutral trim for that load.
    state.cargo = state.activeJob.kind == game::kJobKindNone ? 0 : state.activeJob.crates;
    state.ballast = static_cast<uint8_t>(game::neutralForNormalized(state.cargo));
    state.air = game::airCapacity(state);

    // Restore both freight settlements and generated service berths. The
    // scalar validator has already accepted the berth only when its
    // restoration milestone is present. Position and camera must both be
    // derived from the berth table; leaving cameraXQ4/YQ4 at reset()'s origin
    // renders the sealed map corner after Continue undocks.
    (void)positionAtBerth(state, scalarU8(scalar, kFieldBerth));
}

template <typename Storage>
inline LoadResult load(State &state
                       ,
                       chart::State &chart
                       ,
                       Storage &storage) {
    const Inventory inventory = inspect(storage);
    if (inventory.status != kSlotValid) {
        if (inventory.status == kSlotIncompatible)
            return kIncompatibleSave;
        if (inventory.status == kSlotCorrupt)
            return kCorruptSave;
        return kNoSave;
    }

    Scalar scalar;
    readScalar(storage, static_cast<uint16_t>(kSlotOffset + kPayloadOffset), scalar);
    applyScalar(scalar, state);
    for (uint16_t i = 0; i < kChartBytes; ++i)
        chart.explored[i] = storage.read(static_cast<uint16_t>(kSlotOffset + kPayloadOffset + kScalarBytes + i));
    return kLoaded;
}

// ---------------------------------------------------------------------------
// Save transaction
// ---------------------------------------------------------------------------

// Transaction order:
//   1. erase the single 4 KiB block (commit and payload become 0xFF);
//   2. write page 0 (header, scalar, first chart bytes);
//   3. write page 1 (remaining payload, filler, commit byte last);
//   4. re-read and validate before reporting success.
// This is not power-fail atomic: an interruption after erase can lose the
// previous checkpoint. It never leaves a slot that validates with partial data;
// boot/load reject any torn record and the title offers a clean New Voyage.
template <typename Storage>
inline SaveResult save(const State &state
                       ,
                       const chart::State &chart
                       ,
                       Storage &storage) {
    if (!stateValidForSave(state))
        return kInvalidState;

    storage.eraseBlock(0);

    // The CRC covers header bytes 0..13 and exactly payload_length payload
    // bytes. Both are generated directly from live state, so the transaction
    // needs neither a payload nor a header temporary.
    const uint16_t crc = checkpointCrc(state
                                       ,
                                       chart);

    writeSlot(storage, crc, state
              ,
              chart
    );

    const SlotInfo written = inspectSlot(storage);
    const uint16_t slotCrc =
        static_cast<uint16_t>(storage.read(static_cast<uint16_t>(kSlotOffset + kCrcOffset)) | (static_cast<uint16_t>(storage.read(static_cast<uint16_t>(kSlotOffset + kCrcOffset + 1))) << 8));
    if (written.status != kSlotValid || slotCrc != crc)
        return kWriteFailed;
    return kSaved;
}

// ---------------------------------------------------------------------------
// Explicit new voyage
// ---------------------------------------------------------------------------

template <typename Storage> inline SaveResult newVoyage(State &state, chart::State &chart, Storage &storage) {
    game::reset(state);
    state.hullClass = static_cast<uint8_t>(roster::kDefault);
    state.docked = static_cast<int8_t>(campaign::kTidewall);
    if (!positionAtBerth(state, static_cast<uint8_t>(campaign::kTidewall)))
        return kInvalidState;

    // A new voyage always starts with an empty chart plus the deterministic
    // spawn reveal, and that first checkpoint includes both. No legacy bytes are
    // read or imported; the single slot is erased and rewritten.
    chart::reset(chart);
    chart::revealInitial(chart, state);
    return save(state, chart, storage);
}

#if defined(ARDUINO)
#include <ArduboyFX.h>

#include "fxdata.h"

// Device adapter. The sketch names only voyage_save::save/load/newVoyage; the
// pure code above stays free of Arduino headers for the host tests.
//
// A 4 KiB erase clears the only slot's commit before any new byte is
// programmed. Page 1 is programmed with the commit byte last. Both SPI
// operations complete before the caller resumes music, so no stream refill can
// overlap a cart write.
struct FxStorage {
    static void begin() {
        FX::begin(FX_DATA_PAGE, FX_SAVE_PAGE);
    }

    uint8_t read(uint16_t offset) {
        FX::seekSave(offset);
        const uint8_t value = FX::readPendingUInt8();
        FX::readEnd();
        return value;
    }

    void eraseBlock(uint8_t block) {
        FX::eraseSaveBlock(static_cast<uint16_t>(block * kPagesPerBlock));
        FX::waitWhileBusy();
    }

    void pageBegin(uint16_t page) {
        // programSavePage is the runtime source used by seekSave and
        // eraseSaveBlock; using the compile-time FX_SAVE_PAGE here would write a
        // different page from the one the read-back checks.
        FX::writeEnable();
        FX::seekCommand(SFC_WRITE, static_cast<uint24_t>(FX::programSavePage + page) << 8);
    }

    void pageByte(uint8_t value) {
        FX::writeByte(value);
    }

    void pageEnd() {
        FX::disable();
        FX::waitWhileBusy();
    }
};
#endif

}   // namespace voyage_save

